import sys

data = sys.stdin.read().split()
q = int(data[0])
SIZE = 4093
buckets = [[] for _ in range(SIZE)]
out = []
p = 1
for _ in range(q):
    op = data[p]
    key = int(data[p + 1])
    b = buckets[key % SIZE]
    if op == 'put':
        val = int(data[p + 2])
        p += 3
        for e in b:
            if e[0] == key:
                e[1] = val
                break
        else:
            b.append([key, val])
    elif op == 'get':
        p += 2
        res = -1
        for e in b:
            if e[0] == key:
                res = e[1]
                break
        out.append(res)
    else:
        p += 2
        for idx in range(len(b)):
            if b[idx][0] == key:
                b.pop(idx)
                break
print('\n'.join(map(str, out)))

